const _raw = $('POST /caption/generate').item.json.body || {};
const body = (() => {
  const keys = Object.keys(_raw);
  if (keys.length === 1 && String(keys[0]).trimStart().startsWith('{')) {
    try { return JSON.parse(keys[0]); } catch (_) {}
  }
  return _raw;
})();

const user_id  = $json.user_id;
const image_url = (body.image_url || '').toString().trim();
const style_tag = (body.style_tag || '').toString().trim();
const room_type = (body.room_type || '').toString().trim();

const missing = [];
if (!image_url) missing.push('image_url');
if (!style_tag) missing.push('style_tag');
if (!room_type) missing.push('room_type');
if (missing.length) {
  return [{ json: { _error: { status: 400, body: { error: `missing_fields: ${missing.join(',')}`, code: 'invalid_request' } } } }];
}

return [{ json: { user_id, image_url, style_tag, room_type, started_at_ms: Date.now() } }];

const ctx = $input.item.json;
const arrayBuf = await this.helpers.httpRequest({
  method: 'GET',
  url: ctx.image_url,
  encoding: 'arraybuffer',
});
const b64 = Buffer.from(arrayBuf).toString('base64');
return [{ json: { ...ctx, image_b64: b64, image_mime: 'image/jpeg' } }];

const ctx      = $input.item.json;
const dataUri  = `data:${ctx.image_mime};base64,${ctx.image_b64}`;
const style    = ctx.style_tag;
const room     = ctx.room_type;

const SYSTEM = `You are a precision interior-design captioner. Your captions are used as semantic retrieval documents.

You will receive:
- A photograph of an interior design scene
- Declared room type: ${room}
- Declared design style: ${style}

IMPORTANT: You MUST use both the declared room type and declared style in your output. Do not ignore them.

Write a single flowing caption of 6-10 sentences. Every sentence must pull its weight. Cover ALL of the following - weave them together naturally, do not use bullet points. The declared style (${style}) and room type (${room}) MUST be named at least once in the prose caption.

1. SPATIAL GEOMETRY: room shape, proportions, walls visible, ceiling height/treatment, window/door openings (which wall, size, count), natural light direction and intensity, flooring material, spatial connections.
2. FURNITURE & FIXTURES: every piece, placement relative to walls, orientation, scale, built-ins.
3. OBJECTS & ACCESSORIES: decorative objects, plants, artwork, soft furnishings, lifestyle props, lighting fixtures.
4. MATERIALS & TEXTURES: every surface finish by name (e.g. white-washed oak, honed Carrara marble, brushed brass, limewash plaster, boucle, raw linen).
5. COLOUR PALETTE: dominant background tones, accent colours, highlight colours, warm/cool balance.
6. ARTIFICIAL LIGHTING: fixture types, positions, colour temperature, whether ambient/task/accent.
7. STYLE EXPRESSION (${style}): specific vocabulary, materials, cultural/period references that signal this style.
8. MOOD & ATMOSPHERE: emotional register, perceived time of day, lived-in vs staged.

Output BOTH blocks in this exact order, no preamble:

===CAPTION===
<prose caption - MUST name '${style}' and '${room}' at least once each>
===END===
===SPATIAL===
{
  \"declared_style\": \"${style}\",
  \"declared_room_type\": \"${room}\",
  \"style_signals_observed\": [\"<visible element supporting the declared style>\"],
  \"room_shape\": \"rectangular|square|L-shaped|irregular\",
  \"perceived_proportions\": {\"width_to_depth\": \"wider|deeper|equal\"},
  \"ceiling\": {\"height\": \"low|standard|high|vaulted\", \"treatment\": \"<string or null>\"},
  \"walls_visible\": [\"left\", \"rear\"],
  \"openings\": [{\"wall\": \"rear\", \"type\": \"window\", \"approx_count\": 1}],
  \"natural_light\": {\"direction\": \"front-left\", \"intensity\": \"medium\"},
  \"flooring\": {\"material\": \"<string>\", \"coverage\": \"<string>\"},
  \"furniture\": [{\"type\": \"<string>\", \"wall_relation\": \"<string>\"}],
  \"fixed_features\": []
}
===END_SPATIAL===

Rules for the SPATIAL block:
- 'declared_style' MUST be exactly '${style}' — copy it verbatim.
- 'declared_room_type' MUST be exactly '${room}' — copy it verbatim.
- 'style_signals_observed': only list elements visible in the image that justify the style. Empty array if none — do NOT fabricate.
- All other fields must be based on what is literally visible.\`;

const openrouter_body = {
  model: 'qwen/qwen3-vl-8b-instruct',
  messages: [
    { role: 'system', content: SYSTEM },
    {
      role: 'user',
      content: [
        { type: 'text', text: `Declared room type: ${room}\nDeclared design style: ${style}\n\nAnalyse this interior design image and produce both the CAPTION and SPATIAL blocks.` },
        { type: 'image_url', image_url: { url: dataUri } }
      ]
    }
  ],
  temperature: 0.3,
  max_tokens: 1800
};

return [{ json: { ...ctx, openrouter_body } }];

const ctx     = $('Build caption request').item.json;
const content = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '';

if (!content) {
  return [{ json: { _error: { status: 502, body: { error: 'empty_response', code: 'upstream_error' } } } }];
}

function extractBlock(text, startRe, endRe) {
  const s = text.search(startRe);
  if (s < 0) return null;
  const after = text.slice(s).replace(startRe, '');
  const e = after.search(endRe);
  return (e < 0 ? after : after.slice(0, e)).trim();
}

// Parse CAPTION block
const captionStartRe = /={3,}\s*CAPTION\s*={3,}/i;
const captionEndRe   = /={3,}\s*END\s*={3,}/i;
const caption = extractBlock(content, captionStartRe, captionEndRe);
if (!caption) {
  return [{ json: { _error: { status: 502, body: { error: 'missing_caption_block', code: 'parse_error', raw: content.slice(0, 400) } } } }];
}

// Parse SPATIAL block
const spatialStartRe = /={3,}\s*SPATIAL\s*={3,}/i;
const spatialEndRe   = /={3,}\s*END_SPATIAL\s*={3,}/i;
const spatialRaw = extractBlock(content, spatialStartRe, spatialEndRe);
if (!spatialRaw) {
  return [{ json: { _error: { status: 502, body: { error: 'missing_spatial_block', code: 'spatial_parse_error', raw: content.slice(0, 400) } } } }];
}

let spatial;
try {
  spatial = JSON.parse(spatialRaw);
} catch (e) {
  return [{ json: { _error: { status: 502, body: { error: 'spatial_json_invalid', code: 'spatial_parse_error', raw: spatialRaw.slice(0, 400) } } } }];
}

// Hard validation: declared_style and declared_room_type must match inputs exactly
if (spatial.declared_style !== ctx.style_tag) {
  return [{ json: { _error: { status: 502, body: { error: 'tag_mismatch', code: 'spatial_parse_error', field: 'declared_style', expected: ctx.style_tag, got: spatial.declared_style } } } }];
}
if (spatial.declared_room_type !== ctx.room_type) {
  return [{ json: { _error: { status: 502, body: { error: 'tag_mismatch', code: 'spatial_parse_error', field: 'declared_room_type', expected: ctx.room_type, got: spatial.declared_room_type } } } }];
}

// Soft warning: caption should mention style and room (log only, not a hard fail)
const lc = caption.toLowerCase();
const style_mentioned = lc.includes(ctx.style_tag.toLowerCase());
const room_mentioned  = lc.includes(ctx.room_type.toLowerCase());

const latency_ms = Date.now() - ctx.started_at_ms;
return [{ json: {
  caption,
  spatial_signature: spatial,
  style_tag: ctx.style_tag,
  room_type: ctx.room_type,
  latency_ms,
  caption_mentions_style: style_mentioned,
  caption_mentions_room: room_mentioned
} }];
